INSERT INTO public.system_faq VALUES (1, 1, '如何发起请假申请？', '<p>进入「工作流程 - OA 请假」，点击「发起流程」，填写请假类型、起止时间与事由后提交即可。</p>', 100, 1, '系统管理员', '信息中心', 'admin', '2026-06-01 09:00:00', 'admin', '2026-06-01 09:00:00', 0, 1);
INSERT INTO public.system_faq VALUES (2, 1, '费用报销需要哪些材料？', '<p>请准备：报销单、发票原件、审批流程截图及相关业务说明材料，按财务制度提交审批。</p>', 99, 1, '财务部', '财务部', 'admin', '2026-06-02 09:00:00', 'admin', '2026-06-02 09:00:00', 0, 1);
INSERT INTO public.system_faq VALUES (3, 1, '采购审批流程说明', '<p>采购申请需先填写采购需求单，经部门负责人、采购部及分管领导审批后执行采购。</p>', 98, 1, '采购部', '采购部', 'admin', '2026-06-03 09:00:00', 'admin', '2026-06-03 09:00:00', 0, 1);
INSERT INTO public.system_faq VALUES (4, 2, '如何查询我的待办任务？', '<p>可在门户首页「待办」页签查看，或进入「工作流程 - 待办任务」进行查询与处理。</p>', 97, 1, '系统管理员', '信息中心', 'admin', '2026-06-04 09:00:00', 'admin', '2026-06-04 09:00:00', 0, 1);
INSERT INTO public.system_faq VALUES (5, 3, '系统登录密码如何重置？', '<p>请联系 IT 运维或通过个人中心修改密码；如账号被锁定，需管理员解锁后重新登录。</p>', 96, 1, 'IT 运维', '信息中心', 'admin', '2026-06-05 09:00:00', 'admin', '2026-06-05 09:00:00', 0, 1);
INSERT INTO public.system_faq VALUES (6, 4, '设备报修流程是什么？', '<p>在设备管理模块提交报修单，填写设备编号与故障描述，设备部接单后安排维修并反馈结果。</p>', 95, 1, '设备部', '设备部', 'admin', '2026-06-06 09:00:00', 'admin', '2026-06-06 09:00:00', 0, 1);
INSERT INTO public.system_faq VALUES (7, 5, '如何导出报表数据？', '<p>在报表页面设置查询条件后，点击「导出」按钮即可下载 Excel 文件。</p>', 94, 1, '系统管理员', '信息中心', 'admin', '2026-06-07 09:00:00', 'admin', '2026-06-07 09:00:00', 0, 1);
INSERT INTO public.system_faq VALUES (8, 6, '权限申请找谁审批？', '<p>权限变更需提交权限申请单，由直属领导及系统管理员审批后生效。</p>', 93, 1, '人事部', '人事部', 'admin', '2026-06-08 09:00:00', 'admin', '2026-06-08 09:00:00', 0, 1);
INSERT INTO public.system_faq VALUES (9, 1, '请假审批通过后如何撤销？', '<p>若流程尚未结束，可在「我的流程」中找到对应实例点击撤回；若已全部审批完成，需联系人事部门办理销假手续。</p>', 92, 1, '人事部', '人事部', 'admin', '2026-07-01 19:20:27.501877', 'admin', '2026-07-01 19:20:27.501877', 0, 1);
INSERT INTO public.system_faq VALUES (10, 2, '门户首页快捷入口如何自定义？', '<p>在门户首页长按应用图标进入编辑模式，可添加、删除或调整顺序；保存后仅对当前账号生效。</p>', 91, 1, '系统管理员', '信息中心', 'admin', '2026-07-01 19:20:27.501877', 'admin', '2026-07-01 19:20:27.501877', 0, 1);
INSERT INTO public.system_faq VALUES (11, 2, '如何查看已办任务历史？', '<p>进入「工作流程 → 已办任务」，可按流程名称、发起时间筛选，点击记录可查看审批详情与流转记录。</p>', 90, 1, '系统管理员', '信息中心', 'admin', '2026-07-01 19:20:27.501877', 'admin', '2026-07-01 19:20:27.501877', 0, 1);
INSERT INTO public.system_faq VALUES (12, 3, '忘记登录账号怎么办？', '<p>请联系本部门管理员或信息中心，提供工号与姓名核实身份后，由管理员重置账号或绑定手机号。</p>', 89, 1, 'IT 运维', '信息中心', 'admin', '2026-07-01 19:20:27.501877', 'admin', '2026-07-01 19:20:27.501877', 0, 1);
INSERT INTO public.system_faq VALUES (13, 4, '设备点检记录在哪里填写？', '<p>进入 MES「设备管理 → 点检任务」，选择当日任务后填写点检项结果并提交，异常项需上传现场照片。</p>', 88, 1, '设备部', '设备部', 'admin', '2026-07-01 19:20:27.501877', 'admin', '2026-07-01 19:20:27.501877', 0, 1);
INSERT INTO public.system_faq VALUES (14, 5, '报表导出为空是什么原因？', '<p>请检查查询时间范围是否过窄、筛选条件是否过多，以及当前账号是否有对应数据权限；仍无法导出请联系系统管理员。</p>', 87, 1, '系统管理员', '信息中心', 'admin', '2026-07-01 19:20:27.501877', 'admin', '2026-07-01 19:20:27.501877', 0, 1);
INSERT INTO public.system_faq VALUES (15, 6, '如何申请新增菜单权限？', '<p>提交权限变更申请，说明需访问的菜单与业务理由，经部门负责人审批后由系统管理员在「角色管理」中配置。</p>', 86, 1, '系统管理员', '信息中心', 'admin', '2026-07-01 19:20:27.501877', 'admin', '2026-07-01 19:20:27.501877', 0, 1);
INSERT INTO public.system_faq VALUES (16, 1, '通知公告和常见 QA 有什么区别？', '<p>通知公告用于发布时效性通知；常见 QA 用于沉淀操作说明与常见问题，可在门户首页「常见 QA」页签长期查阅。</p>', 85, 1, '系统管理员', '信息中心', 'admin', '2026-07-01 19:20:27.501877', 'admin', '2026-07-01 19:20:27.501877', 0, 1);
INSERT INTO public.system_faq VALUES (17, 2, '常见问题测试', '<p>test</p>', 0, 1, 'TEST001', '研发部门', '1', '2026-07-01 19:37:34.109', '1', '2026-07-01 19:37:34.109', 0, 1);


